388:           <fieldset class="glazes">
389:             <legend>Glaze</legend>
390:             <div class="glaze-options">
391:               <label class="glaze selected" data-glaze="Sand">
392:                 <input type="radio" name="glaze" value="Sand" checked>
393:                 <span class="swatch" aria-hidden="true" style="--swatch:#c7a77b"></span>
394:                 <span class="g-info">
395:                   <span class="g-name">Sand</span>
396:                   <span class="g-stock">4 in stock</span>
397:                 </span>
398:               </label>
399:               <label class="glaze" data-glaze="Iron">
400:                 <input type="radio" name="glaze" value="Iron">
401:                 <span class="swatch" aria-hidden="true" style="--swatch:#61574e"></span>
402:                 <span class="g-info">
403:                   <span class="g-name">Iron</span>
404:                   <span class="g-stock">2 in stock</span>
405:                 </span>
406:               </label>
