448: <script>
449: (function(){
450:   "use strict";
451:   var PRICE = 42, SHIP = 6, QMIN = 1, QMAX = 4;
452:   var GLAZES = { Sand:{stock:4}, Iron:{stock:2}, Ash:{stock:0} };
453: 
454:   var form        = document.getElementById("order");
455:   var qty         = document.getElementById("qty");
456:   var stockNote   = document.getElementById("qty-stock-note");
457:   var qtyError    = document.getElementById("qty-error");
458:   var panelAlert  = document.getElementById("panel-alert");
459:   var panelStatus = document.getElementById("panel-status");
460:   var costSub     = document.getElementById("cost-sub");
461:   var costShip    = document.getElementById("cost-ship");
462:   var costTotal   = document.getElementById("cost-total");
463:   var radios      = Array.prototype.slice.call(document.querySelectorAll('input[name="glaze"]'));
464:   var labels      = Array.prototype.slice.call(document.querySelectorAll(".glaze"));
465: 
466:   var currentGlaze  = "Sand";
467:   var lastValidQty  = 1;
468:   var hasFailedOnce = false; // the first valid attempt fails recoverably, once
469: 
470:   function fmt(n){ return "$" + n.toFixed(2); }
471:   function cap(){ return Math.min(QMAX, GLAZES[currentGlaze].stock); }
472: 
473:   function renderTotals(q){
474:     costSub.textContent   = fmt(PRICE * q);
475:     costShip.textContent  = fmt(SHIP);
476:     costTotal.textContent = fmt(PRICE * q + SHIP);
477:   }
478: 
479:   function clearQtyError(){
480:     qtyError.textContent = "";
481:     qty.removeAttribute("aria-invalid");
482:   }
483:   function clearPanelAlert(){ panelAlert.textContent = ""; }
484:   function clearSuccess(){ panelStatus.textContent = ""; }
485: 
486:   function updateGlazeUi(){
487:     labels.forEach(function(l){
488:       l.classList.toggle("selected", l.getAttribute("data-glaze") === currentGlaze);
489:     });
490:     qty.max = String(cap());
491:     stockNote.textContent = "Up to " + cap() + " available for " + currentGlaze + ".";
492:   }
493: 
494:   /* ---- quantity validation: empty / small / fractional / excessive ---- */
495:   function readQty(){
496:     var raw = qty.value.trim();
497:     if (raw === "") {
498:       return { ok:false, msg:"Enter a quantity — whole cups from 1 up to " + cap() + "." };
499:     }
500:     var n = Number(raw);
501:     if (!Number.isFinite(n)) {
502:       return { ok:false, msg:"Enter a quantity as digits only." };
503:     }
504:     if (!Number.isInteger(n)) {
505:       return { ok:false, msg:"Whole cups only — enter a number without decimals, such as 1, 2, 3 or 4." };
506:     }
507:     if (n < QMIN) {
508:       return { ok:false, msg:"Quantity must be at least 1 — enter 1 or more." };
509:     }
510:     var c = cap();
511:     if (n > c) {
512:       if (c < QMAX) {
513:         return { ok:false, msg:"Only " + c + " " + currentGlaze + " cups in stock — enter " + c + " or fewer." };
514:       }
515:       return { ok:false, msg:"Maximum " + QMAX + " per order — enter 4 or fewer." };
516:     }
517:     return { ok:true, value:n };
518:   }
519: 
520:   /* ---- glaze switch: clamp quantity to stock and announce ---- */
521:   radios.forEach(function(r){
522:     r.addEventListener("change", function(e){
523:       if (!e.target.checked) return;
524:       currentGlaze = e.target.value;
525:       clearSuccess();
526:       clearPanelAlert();
527:       clearQtyError();
528:       updateGlazeUi();
529:       var c = cap();
530:       if (lastValidQty > c) {
531:         lastValidQty = c;
532:         qty.value = String(c);
533:         renderTotals(c);
534:         panelStatus.textContent =
535:           "Quantity reduced to " + c + " — " + currentGlaze + " has " + c + " in stock.";
536:       }
537:     });
538:   });
539: 
540:   /* ---- editing choices clears stale feedback; totals follow valid input ---- */
541:   qty.addEventListener("input", function(){
542:     clearQtyError();
543:     clearPanelAlert();
544:     clearSuccess();
545:     var r = readQty();
546:     if (r.ok) {
547:       lastValidQty = r.value;
548:       renderTotals(r.value);
549:     }
550:   });
551: 
552:   /* ---- simulated add: first valid attempt fails, retry succeeds ---- */
553:   form.addEventListener("submit", function(e){
554:     e.preventDefault();
555:     clearQtyError();
556:     clearPanelAlert();
557:     var r = readQty();
558:     if (!r.ok) {
559:       qtyError.textContent = r.msg;
560:       qty.setAttribute("aria-invalid", "true");
561:       qty.focus();
562:       return;
563:     }
564:     if (!hasFailedOnce) {
565:       hasFailedOnce = true;
566:       panelAlert.textContent =
567:         "Could not add to the simulated cart — the simulated checkout did not respond. " +
568:         "Your choices are kept (glaze " + currentGlaze + ", quantity " + r.value + "). " +
569:         "Press \u201CAdd to simulated cart\u201D again to retry.";
570:       panelAlert.focus();
571:       return;
572:     }
573:     var q = r.value;
574:     panelStatus.textContent =
575:       "Added to simulated cart: " + q + " \u00D7 " + currentGlaze + " pouring cup" +
576:       (q === 1 ? "" : "s") + " — total " + fmt(PRICE * q + SHIP) +
577:       " (" + fmt(PRICE * q) + " + " + fmt(SHIP) + " shipping). " +
578:       "No real order or payment.";
579:   });
580: 
581:   updateGlazeUi();
582:   renderTotals(lastValidQty);
583: })();
584: </script>
585: </body>
586: </html>

