153:     font-weight:600;
154:     font-size:1.3rem;
155:     margin:0;
156:   }
157:   .price-line{
158:     margin:.15rem 0 1.1rem;
159:     color:var(--ink-soft);
160:     font-variant-numeric:tabular-nums;
161:   }
162:   .price-line strong{color:var(--ink);font-weight:650}
163: 
164:   fieldset.glazes{
165:     border:0;
166:     margin:0 0 1.1rem;
167:     padding:0;
168:   }
169:   fieldset.glazes legend{
170:     padding:0;
171:     font-size:.8rem;
172:     letter-spacing:.1em;
173:     text-transform:uppercase;
174:     color:var(--ink-soft);
175:     margin-bottom:.5rem;
176:   }
177:   .glaze-options{
178:     display:grid;
179:     grid-template-columns:repeat(auto-fit,minmax(9.5rem,1fr));
180:     gap:.5rem;
181:   }
182:   .glaze{
183:     display:flex;
184:     align-items:center;
185:     gap:.6rem;
186:     border:1px solid var(--line);
187:     border-radius:10px;
188:     padding:.6rem .7rem;
189:     cursor:pointer;
190:     min-height:44px;
191:     background:var(--panel);
192:   }
193:   .glaze input[type="radio"]{
194:     width:1.15rem;
195:     height:1.15rem;
196:     margin:0;
197:     flex:none;
198:     accent-color:var(--ink);
199:     cursor:pointer;
200:   }
201:   .glaze input[type="radio"]:focus-visible{
202:     outline:3px solid var(--ink);
203:     outline-offset:2px;
204:   }
205:   .swatch{
206:     width:1.5rem;
207:     height:1.5rem;
208:     flex:none;
209:     border-radius:50%;
210:     background-color:var(--swatch,var(--sand));
211:     border:1px solid rgba(73,60,51,.45);
212:   }
213:   .g-info{display:flex;flex-direction:column;line-height:1.3}
214:   .g-name{font-weight:600}
215:   .g-stock{font-size:.8rem;color:var(--ink-soft)}
216:   .glaze.selected{
217:     border:2px solid var(--ink);
218:     background:#f2e9d8;
219:     padding:calc(.6rem - 1px) calc(.7rem - 1px);
220:   }
221:   .glaze.soldout{border-style:dashed;cursor:not-allowed}
222:   .glaze.soldout .swatch{opacity:.55}
223:   .glaze.soldout .g-name{text-decoration:line-through}
224:   .g-soldout-chip{
225:     display:inline-block;
226:     align-self:flex-start;
227:     font-size:.68rem;
228:     letter-spacing:.06em;
229:     text-transform:uppercase;
230:     color:var(--ink-soft);
231:     border:1px solid var(--ink-soft);
232:     border-radius:999px;
233:     padding:.05rem .45rem;
234:   }
235: 
236:   /* ---------- quantity ---------- */
237:   .qty-field{margin:0 0 1.1rem}
238:   .qty-field label{
239:     display:block;
240:     font-size:.8rem;
241:     letter-spacing:.1em;
242:     text-transform:uppercase;
243:     color:var(--ink-soft);
244:     margin-bottom:.35rem;
245:   }
246:   .qty-field input[type="number"]{
247:     width:min(7rem,100%);
248:     padding:.55rem .6rem;
249:     font:inherit;
250:     color:var(--ink);
251:     background:#fdfaf3;
252:     border:1px solid var(--ink-soft);
253:     border-radius:8px;
254:   }
255:   .qty-field input[type="number"]:focus-visible{
256:     outline:3px solid var(--ink);
257:     outline-offset:2px;
258:   }
259:   .qty-field input[aria-invalid="true"]{border-color:var(--error)}
260:   .hint{
261:     margin:.4rem 0 0;
262:     font-size:.85rem;
263:     color:var(--ink-soft);
264:   }
265:   .field-error{
266:     margin:.4rem 0 0;
267:     font-size:.9rem;
268:     font-weight:600;
269:     color:var(--error);
270:   }
271: 
272:   /* ---------- feedback regions ---------- */
273:   .feedback{border-radius:8px;padding:.7rem .9rem;font-size:.92rem}
274:   .feedback:empty{display:none}
275:   .feedback-error{
276:     background:var(--error-bg);
277:     border-left:3px solid var(--error);
278:     color:var(--error);
279:     margin:0 0 1.1rem;
280:   }
281:   .feedback-ok{
282:     background:var(--ok-bg);
283:     border-left:3px solid var(--ok);
284:     color:var(--ok);
285:     margin:.9rem 0 0;
286:   }
287:   #panel-alert:focus-visible{outline:3px solid var(--error);outline-offset:2px}
288: 
289:   /* ---------- cost + action ---------- */
290:   .cost-action{
291:     display:flex;
292:     flex-wrap:wrap;
293:     align-items:stretch;
294:     gap:1rem;
295:   }
296:   .cost{margin:0;flex:1 1 13rem;font-variant-numeric:tabular-nums}
297:   .cost div{display:flex;justify-content:space-between;gap:1rem;padding:.3rem 0}
298:   .cost dt{color:var(--ink-soft)}
299:   .cost dd{margin:0;text-align:right}
300:   .cost .grand{border-top:2px solid var(--ink);margin-top:.3rem;padding-top:.5rem}
301:   .cost .grand dt{color:var(--ink);font-weight:650}
302:   .cost .grand dd{font-weight:700;font-size:1.15rem}
303:   .add{
304:     flex:1 1 100%;
305:     align-self:end;
306:     min-height:48px;
307:     padding:.8rem 1.2rem;
308:     font:inherit;
309:     font-weight:650;
310:     color:var(--panel);
311:     background:var(--ink);
312:     border:1px solid var(--ink);
313:     border-radius:10px;
314:     cursor:pointer;
315:   }
316:   .add:hover{background:#3d3229}
317:   .add:focus-visible{
318:     outline:3px solid var(--ink);
319:     outline-offset:3px;
320:   }
321:   @media (min-width:30em){
322:     .add{flex:0 1 auto;min-width:14rem}
323:   }
324:   .sim-note{
325:     margin:.9rem 0 0;
326:     font-size:.85rem;
327:     color:var(--ink-soft);
328:   }
329: 
330:   .colophon{
331:     margin:2.5rem 0 0;
332:     font-size:.8rem;
333:     color:var(--ink-soft);
334:   }
335: 
336:   /* ---------- motion (guarded) ---------- */
337:   @media (prefers-reduced-motion: no-preference){
338:     .glaze,.add,.feedback{transition:background-color .15s ease,border-color .15s ease}
339:     .add:active{transform:translateY(1px)}
340:   }
341: </style>
342: </head>
343: <body>
344: <div class="page">
345:   <header class="masthead">
346:     <p class="brand">Kiln Notes</p>
347:     <p class="demo-tag">Fictional demo</p>
348:   </header>
349: 
350:   <main>
351:     <h1>Pouring cup</h1>
352:     <p class="lede">A handleless pouring cup with a small spout.</p>
353: 
354:     <div class="sheet">
355:       <div class="media-specs">
356:         <figure class="plate">
357:           <img
358:             src="assets/pouring-cup.svg"
359:             width="600" height="420"
360:             alt="Schematic drawing of the handleless pouring cup with a small spout, marked 9 cm wide.">
361:           <figcaption>Original schematic illustration of the pouring cup; not a photograph or evidence of glaze texture.</figcaption>
362:         </figure>
363: 
364:         <section class="specs" aria-labelledby="specs-h">
365:           <h2 id="specs-h">Specifications</h2>
366:           <dl>
367:             <div><dt>Capacity</dt><dd>280 ml</dd></div>
368:             <div><dt>Dimensions</dt><dd>9 cm wide × 8 cm tall</dd></div>
369:             <div><dt>Material</dt><dd>Stoneware</dd></div>
370:             <div><dt>Care</dt><dd>Hand-wash; do not use on a stovetop.</dd></div>
371:           </dl>
372:         </section>
373: 
374:         <section class="terms" aria-labelledby="terms-h">
375:           <h2 id="terms-h">Shipping &amp; returns</h2>
376:           <ul>
377:             <li>Flat USD 6 shipping in this fictional checkout; no delivery date is promised.</li>
378:             <li>Unused items may be returned within 14 days; buyer pays return postage.</li>
379:           </ul>
380:         </section>
381:       </div>
382: 
383:       <section class="panel" aria-labelledby="decide-h">
384:         <h2 id="decide-h">Build your order</h2>
385:         <p class="price-line"><strong>USD 42.00</strong> each</p>
386: 
387:         <form id="order" novalidate>
388:           <fieldset class="glazes">
389:             <legend>Glaze</legend>
390:             <div class="glaze-options">
391:               <label class="glaze selected" data-glaze="Sand">
392:                 <input type="radio" name="glaze" value="Sand" checked>
393:                 <span class="swatch" aria-hidden="true" style="--swatch:#c7a77b"></span>
394:                 <span class="g-info">
395:                   <span class="g-name">Sand</span>
396:                   <span class="g-stock">4 in stock</span>
397:                 </span>
398:               </label>
399:               <label class="glaze" data-glaze="Iron">
400:                 <input type="radio" name="glaze" value="Iron">
401:                 <span class="swatch" aria-hidden="true" style="--swatch:#61574e"></span>
402:                 <span class="g-info">
403:                   <span class="g-name">Iron</span>
404:                   <span class="g-stock">2 in stock</span>
405:                 </span>
406:               </label>
407:               <label class="glaze soldout" data-glaze="Ash">
408:                 <input type="radio" name="glaze" value="Ash" disabled>
409:                 <span class="swatch" aria-hidden="true" style="--swatch:#a5aaa2"></span>
410:                 <span class="g-info">
411:                   <span class="g-name">Ash</span>
412:                   <span class="g-stock"><span class="g-soldout-chip">Sold out</span></span>
413:                 </span>
414:               </label>
415:             </div>
416:           </fieldset>
417: 
418:           <div class="qty-field">
419:             <label for="qty">Quantity</label>
420:             <input id="qty" name="quantity" type="number" value="1"
421:                    min="1" max="4" step="1" inputmode="numeric" required
422:                    aria-describedby="qty-hint qty-error">
423:             <p id="qty-hint" class="hint">Whole cups only. <span id="qty-stock-note">Up to 4 available for Sand.</span></p>
424:             <p id="qty-error" class="field-error" role="alert"></p>
425:           </div>
426: 
427:           <p id="panel-alert" class="feedback feedback-error" role="alert" tabindex="-1"></p>
428: 
429:           <div class="cost-action">
430:             <dl class="cost">
431:               <div><dt>Item subtotal</dt><dd id="cost-sub">$42.00</dd></div>
432:               <div><dt>Shipping (flat)</dt><dd id="cost-ship">$6.00</dd></div>
433:               <div class="grand"><dt>Total</dt><dd id="cost-total">$48.00</dd></div>
434:             </dl>
435:             <button type="submit" class="add">Add to simulated cart</button>
436:           </div>
437: 
438:           <p id="panel-status" class="feedback feedback-ok" role="status"></p>
439:           <p class="sim-note">Simulated cart — no real order is placed and no payment is taken.</p>
440:         </form>
441:       </section>
442:     </div>
443: 
444:     <p class="colophon">Kiln Notes is a fictional brand; this page is a UI demo with no real store behind it.</p>
445:   </main>
446: </div>
447: 
448: <script>
449: (function(){
450:   "use strict";
451:   var PRICE = 42, SHIP = 6, QMIN = 1, QMAX = 4;
452:   var GLAZES = { Sand:{stock:4}, Iron:{stock:2}, Ash:{stock:0} };
453: 
454:   var form        = document.getElementById("order");
455:   var qty         = document.getElementById("qty");
456:   var stockNote   = document.getElementById("qty-stock-note");
457:   var qtyError    = document.getElementById("qty-error");
458:   var panelAlert  = document.getElementById("panel-alert");
459:   var panelStatus = document.getElementById("panel-status");
460:   var costSub     = document.getElementById("cost-sub");
461:   var costShip    = document.getElementById("cost-ship");
462:   var costTotal   = document.getElementById("cost-total");
463:   var radios      = Array.prototype.slice.call(document.querySelectorAll('input[name="glaze"]'));
464:   var labels      = Array.prototype.slice.call(document.querySelectorAll(".glaze"));
465: 
466:   var currentGlaze  = "Sand";
467:   var lastValidQty  = 1;
468:   var hasFailedOnce = false; // the first valid attempt fails recoverably, once
469: 
470:   function fmt(n){ return "$" + n.toFixed(2); }
471:   function cap(){ return Math.min(QMAX, GLAZES[currentGlaze].stock); }
472: 
473:   function renderTotals(q){
474:     costSub.textContent   = fmt(PRICE * q);
475:     costShip.textContent  = fmt(SHIP);
476:     costTotal.textContent = fmt(PRICE * q + SHIP);
477:   }
478: 
479:   function clearQtyError(){
480:     qtyError.textContent = "";
481:     qty.removeAttribute("aria-invalid");
482:   }
483:   function clearPanelAlert(){ panelAlert.textContent = ""; }
484:   function clearSuccess(){ panelStatus.textContent = ""; }
485: 
486:   function updateGlazeUi(){
487:     labels.forEach(function(l){
488:       l.classList.toggle("selected", l.getAttribute("data-glaze") === currentGlaze);
489:     });
490:     qty.max = String(cap());
491:     stockNote.textContent = "Up to " + cap() + " available for " + currentGlaze + ".";
492:   }
493: 
494:   /* ---- quantity validation: empty / small / fractional / excessive ---- */
495:   function readQty(){
496:     var raw = qty.value.trim();
497:     if (raw === "") {
498:       return { ok:false, msg:"Enter a quantity — whole cups from 1 up to " + cap() + "." };
499:     }
500:     var n = Number(raw);
501:     if (!Number.isFinite(n)) {
502:       return { ok:false, msg:"Enter a quantity as digits only." };
503:     }
504:     if (!Number.isInteger(n)) {
505:       return { ok:false, msg:"Whole cups only — enter a number without decimals, such as 1, 2, 3 or 4." };
506:     }
507:     if (n < QMIN) {
508:       return { ok:false, msg:"Quantity must be at least 1 — enter 1 or more." };
509:     }
510:     var c = cap();
511:     if (n > c) {
512:       if (c < QMAX) {
513:         return { ok:false, msg:"Only " + c + " " + currentGlaze + " cups in stock — enter " + c + " or fewer." };
514:       }
515:       return { ok:false, msg:"Maximum " + QMAX + " per order — enter 4 or fewer." };
516:     }
517:     return { ok:true, value:n };
518:   }
519: 
520:   /* ---- glaze switch: clamp quantity to stock and announce ---- */
521:   radios.forEach(function(r){
522:     r.addEventListener("change", function(e){
523:       if (!e.target.checked) return;
524:       currentGlaze = e.target.value;
525:       clearSuccess();
526:       clearPanelAlert();
527:       clearQtyError();
528:       updateGlazeUi();
529:       var c = cap();
530:       if (lastValidQty > c) {
531:         lastValidQty = c;
532:         qty.value = String(c);
533:         renderTotals(c);
534:         panelStatus.textContent =
535:           "Quantity reduced to " + c + " — " + currentGlaze + " has " + c + " in stock.";
536:       }
537:     });
538:   });
539: 
540:   /* ---- editing choices clears stale feedback; totals follow valid input ---- */
541:   qty.addEventListener("input", function(){
542:     clearQtyError();
543:     clearPanelAlert();
544:     clearSuccess();
545:     var r = readQty();
546:     if (r.ok) {
547:       lastValidQty = r.value;
548:       renderTotals(r.value);
549:     }
550:   });
551: 
552:   /* ---- simulated add: first valid attempt fails, retry succeeds ---- */
553:   form.addEventListener("submit", function(e){
554:     e.preventDefault();
555:     clearQtyError();
556:     clearPanelAlert();
557:     var r = readQty();
558:     if (!r.ok) {
559:       qtyError.textContent = r.msg;
560:       qty.setAttribute("aria-invalid", "true");
561:       qty.focus();
562:       return;
563:     }
564:     if (!hasFailedOnce) {
565:       hasFailedOnce = true;
566:       panelAlert.textContent =
567:         "Could not add to the simulated cart — the simulated checkout did not respond. " +
568:         "Your choices are kept (glaze " + currentGlaze + ", quantity " + r.value + "). " +
569:         "Press \u201CAdd to simulated cart\u201D again to retry.";
570:       panelAlert.focus();
571:       return;
572:     }
573:     var q = r.value;
574:     panelStatus.textContent =
575:       "Added to simulated cart: " + q + " \u00D7 " + currentGlaze + " pouring cup" +
576:       (q === 1 ? "" : "s") + " — total " + fmt(PRICE * q + SHIP) +
577:       " (" + fmt(PRICE * q) + " + " + fmt(SHIP) + " shipping). " +
578:       "No real order or payment.";
579:   });
580: 
581:   updateGlazeUi();
582:   renderTotals(lastValidQty);
583: })();
584: </script>
585: </body>
586: </html>
